end
for start in ((-2.0, 1.0), (0.0, 0.0), (-0.1, 0.5), (2.0, 0.0))
    status, x, y, obj = solve_from(start...)
    println("start ", rpad(start, 12), status, ": x = ", round(x; digits = 4), ", y = ", round(y; digits = 4) + 0.0,
            ", objective = ", round(obj; digits = 4))
